  labEl('area-total').textContent='Jumlah dipilih '+(Number.isInteger(sum)?'= ':'\u2248 ')+labFmt(sum)+' cm\xB2';labEl('area-formula').textContent=chosen.length===parts.length?'Rumus keseluruhan: '+LESSON_DATA[a.shape].surface.formula:'Rumus keseluruhan akan muncul selepas semua permukaan dipilih.';
